          registration_mode: 'Modo de registro autoatendimento. self_serve = qualquer um pode registrar uma conta; invite_only = registro público desativado e apenas Proprietários/Administradores podem convidar. Tem efeito imediato após salvar, mas use self_serve com cuidado (a internet pública enviará registros de spam).',
          default_tenant_mode: 'Provisionamento de espaço de trabalho após registro público. create_personal cria um espaço de Proprietário; tenantless cria apenas a conta até que o usuário aceite um convite ou crie um espaço. Aplica apenas a novos usuários.',
          complex_password_enabled: 'Se deve exigir senhas complexas. Quando ativado, as senhas devem conter letras maiúsculas e minúsculas, números e caracteres especiais. Mudanças têm efeito imediato e só se aplicam a usuários recém-registrados ou novas mudanças/reset de senha. Caracteres especiais incluem {specialChars}'
